  "text": "Панель смыва из пластика для унитазов c двумя режимами смыва. Две клавиши, фронтальная установка, стандартное крепление.\n\nРазмеры (ш x в x г): 245 x 165 x 8 мм\n\nЦвет: хром глянцевый, контур клавиш хром матовый\n\nВнимание:\n\nПанели смыва TECEspring совместимы только с застенными модулями TECEspring\n\nПримечание:\n\nМинимальная толщина обшивки стены – 20 мм.",
