  "text": "Металлическая панель смыва для унитаза TECEspring SL, нержавеющая сталь, сатин, покрытие против отпечатков пальцев. Панель смыва из нержавеющей стали для унитазов c автоматическим двухрежимным смывом. Две клавиши, объемная форма, фронтальная установка, стандартное крепление.\n\nЭлектропитание: 100-240 В, 50/60 Гц (блок питания входит в комплект\n\nпоставки).\n\nРазмеры (ш x в x г): 258 х 180 х 10 мм\n\nЦвет: нержавеющая сталь, сатин (с покрытием против отпечатков пальцев)\n\nВнимание:\n\nПанели смыва TECEspring совместимы только с застенными модулями TECEspring.\n\nПримечание:\n\nМинимальная толщина обшивки стены – 20 мм.",
