  "text": "Комплект с модулем для унитаза и панелью смыва для монтажа перед стеной.\n\nХарактеристики TECEspring:\n\n• Несущая монтажная рама с порошковым покрытием поверхности\n\n• Предварительно собранный сливной бачок\n\n• Соединение для сливного бачка с наружной резьбой R 1/2\"\n\n• Монтаж заливного вентиля сверху или сзади бачка\n\n• Объем бачка 6 л: настраиваемый объем малого смыва – от 3 до 5 л, большого – от 4 до 6 л\n\n• Изоляция для предотвращения образования конденсата\n\n• Съемный шланг заливного клапана\n\n• Настройка скорости смыва: регулировка сливного клапана для предотвращения разбрызгивания воды из чаши унитаза\n\nКомплект поставки:\n\n• Застенный модуль TECEspring base\n\n• Панель смыва TECEspring\n\n• Две крепежные шпильки M 12 с гайками (для унитаза)\n\n• Соединительный комплект унитаза, включая защитные заглушки\n\n• Прокладка звукоизоляционная для унитаза\n\n• Комплект крепежных элементов для установки модуля\n\n• Фановый отвод для подключения к канализации DN 110\n\nДополнительно приобретается:\n\n• Горизонтальная фановая труба DN 90, арт. AF042300-L18 (опционально)\n\n• Фановый отвод DN90, арт. AF042300-L23 (опционально)\n\n• Адаптер DN 90 / DN 110, арт. AF042300-L19 (опционально)",
